import itertools

def simulate(n, k, config):
    # Convert config to list for mutability if necessary, but we're already using lists
    # To handle large configurations, avoid deep recursion and be efficient
    current_config = list(config)
    visited = set()

    while True:
        # Count adjacencies
        adj = 0
        for i in range(len(current_config) - 1):
            if current_config[i] != current_config[i+1]:
                adj += 1
        if adj <= 1:
            return True

        state = tuple(current_config)
        if state in visited:
            return False
        visited.add(state)

        idx = k - 1
        coin = current_config[idx]

        start = idx
        while start > 0 and current_config[start-1] == coin:
            start -= 1
        end = idx
        while end < len(current_config) - 1 and current_config[end+1] == coin:
            end += 1

        subsequence = current_config[start:end+1]
        remaining = current_config[:start] + current_config[end+1:]
        current_config = subsequence + remaining

def check_k(n, k):
    # Use combinations to get unique configs
    # 0 represents A, 1 represents C
    # For n=3, 20 configs.
    # For n=4, 70 configs.
    # For n=5, 252 configs.
    configs = []
    for combo in itertools.combinations(range(2*n), n):
        config = [0] * (2*n)
        for i in combo:
            config[i] = 1
        configs.append(tuple(config))

    for config in configs:
        if not simulate(n, k, config):
            return False
    return True

for n in [1, 2, 3, 4]:
    results = []
    for k in range(1, 2*n + 1):
        results.append(check_k(n, k))
    print(f"n={n}: {results}")

